<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Stockroom | Product inventory</title><link rel="stylesheet" href="assets/bootstrap.min.css"><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head>
<body><main class="container py-4 py-md-5"><header class="mb-4 d-flex justify-content-between align-items-center"><div class="brand">stockroom<span>.</span></div><span class="badge rounded-pill text-bg-light border">Product inventory</span></header>
<div class="mb-4"><p class="eyebrow">A CLEAR VIEW OF YOUR STOCK</p><h1>Small details. Accurate totals.</h1><p class="text-secondary">Add products, keep quantities up to date, and see what your stock is worth.</p></div>
<section class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><h2 class="h5 mb-4" id="form-title">Add a product</h2><form id="product-form"><input type="hidden" id="product-id"><div class="row g-3"><div class="col-md-5"><label class="form-label" for="name">Product name</label><input class="form-control" id="name" name="name" type="text" maxlength="200" required autocomplete="off" placeholder="e.g. Canvas tote"></div><div class="col-md-3"><label class="form-label" for="quantity">Quantity in stock</label><input class="form-control" id="quantity" name="quantity" type="text" inputmode="numeric" pattern="[0-9]{1,5}" required placeholder="0"><div class="form-text">Whole numbers, 0–99999</div></div><div class="col-md-4"><label class="form-label" for="price">Price per item</label><input class="form-control" id="price" name="price" type="text" inputmode="decimal" pattern="[0-9]{1,5}([.][0-9]{1,2})?" required placeholder="0.00"><div class="form-text">Up to 99999.99; use a decimal point</div></div></div><div class="d-flex flex-wrap gap-2 align-items-center mt-4"><button id="save" class="btn btn-success px-4" type="submit" disabled>Add product</button><button id="cancel" class="btn btn-outline-secondary" type="button" hidden>Cancel edit</button><span class="small text-secondary ms-md-auto">Line value: <strong id="preview">0.00</strong></span></div></form><div id="message" class="mt-3 mb-0" role="status" aria-live="polite"></div></div></section>
<section class="card border-0 shadow-sm"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 mb-1">Inventory</h2><p class="small text-secondary mb-0">Oldest submission first · All times UTC</p></div><button id="refresh" type="button" class="btn btn-outline-secondary btn-sm">Refresh list</button></div><div class="table-responsive"><table class="table align-middle mb-0"><caption class="visually-hidden">Submitted products and their total stock value</caption><thead><tr><th scope="col">Product name</th><th scope="col" class="text-end">Quantity in stock</th><th scope="col" class="text-end">Price per item</th><th scope="col">Datetime submitted</th><th scope="col" class="text-end">Total value number</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr></thead><tbody id="rows"><tr><td colspan="6" class="text-secondary py-4">Loading products…</td></tr></tbody><tfoot><tr><th colspan="4" scope="row">Sum total</th><td id="grand-total" class="text-end fw-bold">—</td><td></td></tr></tfoot></table></div></div></section><footer class="mt-4 small text-secondary">Values use two decimal places. Changes are saved to a JSON file on the server.</footer><noscript><p class="alert alert-warning mt-3">Please enable JavaScript to submit this Ajax form.</p></noscript></main></body></html>
